#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-24

# Builds Tower and assembles a real .app bundle.
# Xcode is NOT required; SwiftPM plus a hand-written Info.plist is enough.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

# "Tower" (2026-08-09). Third and final name: "HQ Claude Limits" -> "Limits" ->
# "Tower", all on the same day, so the reasoning is worth keeping.
#
# Why not "Limits": only ~1 of the app's 7 surfaces is limits. It also carries
# OpenRouter balance + spend trend, live agent sessions per repo (AgentProbe /
# AgentSummary), stay-vs-switch routing, and threshold alerts. (The Jarvis voice
# loop was part of that list when the name was chosen; #72 removed it.) It
# answers a DECISION - can I start work now, on which account, and what
# is already running - not a measurement. That is air-traffic control: which
# runways are clear, what is already in the air, where to route.
#
# Why the old "HQ Claude Limits" was wrong: it named one provider out of three.
#
# v0.1 changed BIN_NAME (HQClaudeLimits -> Tower) and CFBundleIdentifier
# (ai.yonatan-hq.claude-limits -> ai.yonyon.tower). macOS keys privacy grants and
# the login item off the bundle id, so the app migrates the old install on first
# launch (LegacyInstallMigration) and install.sh stops, replaces and re-registers
# an install that still runs the old executable.
#
# RENAMING THE APP MOVES THE BUNDLE PATH. LaunchAtLogin registers a bundle URL,
# so a rename orphans the old bundle with the Login Item still pointing at it -
# next reboot launches the STALE binary. install.sh now handles this; if you
# rename again, keep that migration step.
APP_NAME="Tower"
BIN_NAME="Tower"
BUNDLE_IDENTIFIER="ai.yonyon.tower"
OUT="${1:-$ROOT/dist}"
APP="$OUT/$APP_NAME.app"

# Build stamp. CFBundleVersion carries the short git sha so an installed bundle
# answers which commit built it and scripts/update.sh can compare the installed
# build against the newest artifact; it was "1" on every build before, which is
# what made a stale install indistinguishable from a current one. "unknown"
# outside a git checkout.
BUILD_SHA="$(git -C "$ROOT" rev-parse HEAD 2>/dev/null | cut -c1-7 || true)"
[ -n "$BUILD_SHA" ] || BUILD_SHA="unknown"
# A dirty tree builds code that is not the stamped commit; mark it so the
# stamp can never prefix-match a CI artifact's full sha and fool update.sh's
# already-current check.
if [ "$BUILD_SHA" != "unknown" ] && [ -n "$(git -C "$ROOT" status -s 2>/dev/null)" ]; then
  BUILD_SHA="$BUILD_SHA-dirty"
fi

# Brand-mark ship mode: TOWER_BRAND_MARKS=local|off, default local. The real
# extracted app icons under Resources/BrandMarks are the products' own marks,
# so they ship in operator-local builds only; release-app.yml builds with
# `off`. With the directory absent every row falls back to the monogram or
# grayscale template tile, never a blank. The mode is stamped into Info.plist
# as TowerBrandMarks so `selftest` can assert the bundle matches its stamp.
BRAND_MARKS="${TOWER_BRAND_MARKS:-local}"
case "$BRAND_MARKS" in
  local|off) ;;
  *) echo "ERROR: TOWER_BRAND_MARKS must be local or off (got '$BRAND_MARKS')" >&2; exit 1 ;;
esac

# SDK selection. Newer CommandLineTools pair swift 6.x with SDKs where SwiftUI
# property wrappers (@State, @Binding, ...) became compiler macros. On those SDKs
# the CLT macro loader can fail with "plugin for module 'SwiftUIMacros' not
# found"; @State then silently stops expanding and every Button closure that
# mutates it reports the bogus "cannot use mutating member on immutable value:
# 'self' is immutable" at the closure (AppUI.swift RestingDrawer.disclosed,
# seen 2026-09). The property wrapper is NOT the bug: the fix is to build
# against an SDK where the macro plugin loads. Probe each candidate SDK with a
# one-file reproduction of the failing pattern, newest first, and pick the
# first that typechecks. CI (macos-15 runner, Xcode toolchain) passes the
# newest probe and is unaffected. If nothing passes, build with the toolchain
# default and let the real compiler errors surface.
probe_dir="$(mktemp -d)"
trap 'rm -rf "$probe_dir"' EXIT
cat > "$probe_dir/Probe.swift" <<'EOF'
import SwiftUI
struct ProbeView: View {
    @State private var disclosed: Set<String> = []
    var body: some View {
        Button("probe") {
            if disclosed.isEmpty { disclosed.insert("x") } else { disclosed.remove("x") }
        }
    }
}
EOF
sdk_candidates=()
while IFS= read -r sdk; do
  # Resolve symlinks (MacOSX.sdk -> MacOSX27.0.sdk) so we probe each real SDK once.
  real="$(cd "$sdk" && pwd -P)"
  sdk_candidates+=("$real")
done < <(ls -d "$(xcode-select -p)"/SDKs/MacOSX*.sdk 2>/dev/null | grep -v '/MacOSX.sdk$' | sort -Vr)
# Env SDKROOT wins when the caller pinned one, otherwise probe newest first.
if [ -n "${SDKROOT:-}" ]; then
  sdk_candidates=("$SDKROOT" ${sdk_candidates[@]+"${sdk_candidates[@]}"})
fi
chosen_sdk=""
# ${arr[@]+...} guard: macOS ships bash 3.2, where expanding an EMPTY array
# under set -u is an "unbound variable" error instead of zero iterations.
for sdk in ${sdk_candidates[@]+"${sdk_candidates[@]}"}; do
  if env -u SDKROOT swiftc -typecheck -sdk "$sdk" \
       -target "$(uname -m)-apple-macos14.0" "$probe_dir/Probe.swift" >/dev/null 2>&1; then
    chosen_sdk="$sdk"
    break
  fi
done
if [ -n "$chosen_sdk" ]; then
  echo "==> swift build (SDK: "$(basename "$chosen_sdk")")"
  SDKROOT="$chosen_sdk" swift build -c release
else
  echo "==> swift build (toolchain default SDK; no probed SDK loaded SwiftUI macros)"
  swift build -c release
fi

echo "==> assembling $APP"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp ".build/release/Tower" "$APP/Contents/MacOS/$BIN_NAME"

# Provider brand marks: real extracted app icons under BrandMarks/ (rendered
# .original), plus the older grayscale template marks under icons/. BrandMarks
# is local-only: `off` leaves it out of the bundle entirely.
if [ -d "$ROOT/Resources/icons" ]; then
  cp -R "$ROOT/Resources/icons" "$APP/Contents/Resources/icons"
fi
# A checkout ships no product icons (scripts/extract-brand-marks.sh copies them
# from installed apps). With none extracted, local means off, so the stamp in
# Info.plist still matches what the bundle carries.
if [ "$BRAND_MARKS" = "local" ] && [ ! -f "$ROOT/Resources/BrandMarks/claude.png" ]; then
  echo "==> no extracted brand marks (run scripts/extract-brand-marks.sh); building with off"
  BRAND_MARKS="off"
fi
if [ "$BRAND_MARKS" = "local" ]; then
  mkdir -p "$APP/Contents/Resources/BrandMarks"
  cp "$ROOT"/Resources/BrandMarks/*.png "$APP/Contents/Resources/BrandMarks/"
fi
echo "==> brand marks: $BRAND_MARKS"

# printf, NOT a heredoc. `cat > file <<PLIST` writes the whole body into a PIPE
# inside do_redirections BEFORE exec'ing the reader, so once the body passes the
# pipe buffer the write blocks or truncates. The threshold is environmental, not
# fixed: on 2026-07-29, on a machine running ~15 concurrent agents, this exact
# heredoc produced a ZERO-BYTE Info.plist. The build reported success, the bundle
# assembled, codesign passed, and the installed app died with "executable is
# missing" because macOS could not read the plist that names the executable.
# printf is a bash builtin: no pipe, no reader to exec, no size threshold.
printf '%s\n' \
  '<?xml version="1.0" encoding="UTF-8"?>' \
  '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">' \
  '<plist version="1.0">' \
  '<dict>' \
  "  <key>CFBundleName</key><string>$APP_NAME</string>" \
  "  <key>CFBundleDisplayName</key><string>$APP_NAME</string>" \
  "  <key>CFBundleIdentifier</key><string>$BUNDLE_IDENTIFIER</string>" \
  "  <key>CFBundleExecutable</key><string>$BIN_NAME</string>" \
  '  <key>CFBundlePackageType</key><string>APPL</string>' \
  '  <key>CFBundleShortVersionString</key><string>0.1.0</string>' \
  "  <key>CFBundleVersion</key><string>$BUILD_SHA</string>" \
  '  <key>LSMinimumSystemVersion</key><string>14.0</string>' \
  '  <!-- menubar-only: no Dock icon, no main window -->' \
  '  <key>LSUIElement</key><true/>' \
  '  <key>NSHighResolutionCapable</key><true/>' \
  "  <key>TowerBrandMarks</key><string>$BRAND_MARKS</string>" \
  '</dict>' \
  '</plist>' \
  > "$APP/Contents/Info.plist"

# Fail loudly rather than shipping a bundle macOS cannot open. A zero-byte or
# unparseable plist is the failure mode that got us here, and it is silent.
if ! plutil -lint "$APP/Contents/Info.plist" >/dev/null 2>&1; then
  echo "   ERROR: Info.plist is missing or unparseable, refusing to ship this bundle" >&2
  exit 1
fi
if [ "$(plutil -extract CFBundleIdentifier raw "$APP/Contents/Info.plist")" != "$BUNDLE_IDENTIFIER" ]; then
  echo "   ERROR: assembled bundle identifier does not match the stable Tower identity" >&2
  exit 1
fi

# Signing: "Tower Dev" when this machine has it, ad-hoc otherwise. The rule lives in
# sign-app.sh because install.sh applies the same one to downloaded bundles (#121). The
# app handles an ad-hoc build (fallback to the CLI credential, one re-create of the active
# seat's item per launch, see SystemClaudeSeatKeychain).
# shellcheck source=scripts/sign-app.sh
. "$ROOT/scripts/sign-app.sh"
tower_sign_app "$APP" yes
signed="$TOWER_SIGNED"

echo ""
echo "Built: $APP (signature: ${signed:-none})"
echo "Run GUI : open \"$APP\""
echo "Run CLI : \"$APP/Contents/MacOS/$BIN_NAME\" status"
